content='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    rects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            area = (r1-r0+1)*(c1-c0+1)
            # A substantial, nearly rectangular same-color component is an object;
            # other isolated colored marks are background speckles.
            if (r1-r0+1) >= 2 and (c1-c0+1) >= 2 and len(comp)/area >= 0.62 and area >= 6:
                rects.append((r0,r1,c0,c1,color))
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r0,r1,c0,c1,color in rects:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c] = color
    return out
'''
